          talk: '1784年、博多湾に浮かぶ志賀島で、農民が田んぼの溝を直していると、一辺2.3センチほどの小さな金のはんこが出てきました。刻まれていたのは「漢委奴国王」の5文字。57年に倭の奴国の王が後漢の光武帝に使いを送り、もらったものだと考えられています。中国の皇帝が、周りの国の王に称号と印をあたえる。これが冊封です。はんこを受け取ることは、皇帝の家来になったしるしでした。それでも、なぜ遠くの王たちは進んで欲しがったのでしょうか。',
